-- OM-015：收货人/手机号冗余列（管理端检索走索引，不再 JSON_EXTRACT 全表扫）
UPDATE t_order_1 SET receiver = JSON_UNQUOTE(JSON_EXTRACT(address_json, '$.receiver')), phone = JSON_UNQUOTE(JSON_EXTRACT(address_json, '$.phone')) WHERE receiver IS NULL;

